<script setup lang="ts">import AdminLayout from '@/Layouts/AdminLayout.vue';import {Head,Link,router} from '@inertiajs/vue3';import {ref} from 'vue';defineOptions({layout:AdminLayout});const props=defineProps<{submissions:any;filters:any}>();const search=ref(props.filters.search||'');const status=ref(props.filters.status||'');function filter(){router.get('/admin/submissions',{search:search.value,status:status.value},{preserveState:true,replace:true})}</script>
<template><Head title="Manajemen Submission"/><div class="min-h-screen bg-neutral-100 p-6 text-neutral-900"><main class="mx-auto max-w-7xl"><p class="text-sm font-bold uppercase tracking-widest text-orange-600">Admin Program</p><h1 class="text-4xl font-bold">Submission</h1><form class="mt-8 flex flex-wrap gap-3" @submit.prevent="filter"><input v-model="search" class="rounded-xl border-neutral-300" placeholder="Cari nomor atau lagu"><select v-model="status" class="rounded-xl border-neutral-300"><option value="">Semua status</option><option v-for="s in ['submitted','administrative_review','revision_requested','eligible','curation','shortlisted','selected','not_selected']" :key="s">{{s}}</option></select><button class="rounded-xl bg-neutral-900 px-5 py-2 text-white">Filter</button></form><div class="mt-6 overflow-x-auto rounded-2xl bg-white shadow-sm"><table class="w-full text-left"><thead><tr><th>Nomor</th><th>Nama</th><th>Lagu</th><th>Kota</th><th>Status</th></tr></thead><tbody><tr v-for="item in submissions.data" :key="item.id" class="border-t"><td><Link :href="`/admin/submissions/${item.id}`" class="font-mono text-orange-700">{{item.registration_number}}</Link></td><td>{{item.applicant?.full_name}}</td><td>{{item.song?.title}}<small class="block text-neutral-500">{{item.song?.genre}}</small></td><td>{{item.applicant?.city}}</td><td>{{item.status}}</td></tr></tbody></table></div></main></div></template><style scoped>th,td{padding:1rem 1.25rem}th{font-size:.75rem;text-transform:uppercase;color:#737373}</style>
